<?php require_once 'bootstrap.php';$public=isset($_GET['public']);$u=$public?null:require_login();$events=db()->query("SELECT e.*,(SELECT COUNT(*) FROM event_registrations er WHERE er.event_sic_id=e.sic_id AND er.status='REGISTERED') registrations FROM events e WHERE status='PUBLISHED' ORDER BY starts_at")->fetchAll();$pageTitle='Eventi';require '_header.php';?><section class="section-head"><div><span class="eyebrow">Vivi la Community</span><h1>Eventi</h1><p>Club, Interclub, webinar, viaggi, SAT, volontariato e lifestyle.</p></div><?php if($u&&is_admin($u['sic_id'])):?><a class="btn primary small" href="event-builder.php">＋ Crea</a><?php endif;?></section><div class="event-list"><?php foreach($events as $e):?><article class="event-card"><div class="event-icon"><?=match($e['type']){'WEBINAR'=>'💻','VIAGGIO'=>'✈️','INTERCLUB'=>'🤝','VOLONTARIATO'=>'❤️',default=>'📅'}?></div><div><span class="eyebrow"><?=h($e['type'])?></span><h3><?=h($e['title'])?></h3><p><?=h($e['venue'])?> · <?=h($e['starts_at'])?></p><small><?=h((string)$e['registrations'])?> iscritti · ◆ <?=h((string)$e['drx_reward'])?> DRX</small><?php if($u):?><form method="post" action="action.php"><input type="hidden" name="<?=CSRF_KEY?>" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="event_register"><input type="hidden" name="event_sic_id" value="<?=h($e['sic_id'])?>"><input type="hidden" name="return" value="events.php"><button class="btn small">Partecipa</button></form><?php endif;?><a class="btn small" href="event-detail.php?event=<?=urlencode($e['sic_id'])?>">Apri evento</a></div></article><?php endforeach;?></div><?php require '_footer.php';?>